const response = $json.choices[0].message.content;
const taskType = $json.body.task?.split(' ')[0]?.toLowerCase() || 'generate';

let formattedResponse = response;

if (taskType === 'generate' || taskType === 'refactor') {
  const codeBlockMatch = response.match(/```[\s\S]*?```/g);
  if (codeBlockMatch) {
    formattedResponse = {
      explanation: response.replace(/```[\s\S]*?```/g, '').trim(),
      code: codeBlockMap(codeBlockMatch[0])
    };
  }
}

function codeBlockMap(block) {
  return block.replace(/^```\w*\n/, '').replace(/\n```$/, '');
}

return [{
  json: {
    success: true,
    task: taskType,
    response: formattedResponse,
    rawResponse: response,
    model: $json.model,
    usage: $json.usage
  }
}];

const error = $json.error || 'Unknown error';
return [{
  json: {
    success: false,
    error: error.message || error,
    task: $json.body?.task
  }
}];

const fs = require('fs');
const path = require('path');

const { code, language, filename } = $json.body;
if (!code) return [{ json: { error: 'No code provided' } }];

const ext = language === 'python' ? 'py' : language === 'javascript' ? 'js' : language === 'typescript' ? 'ts' : 'txt';
const fileName = filename || `generated_${Date.now()}.${ext}`;
const savePath = path.join('/tmp/n8n-code-output', fileName);

if (!fs.existsSync(path.dirname(savePath))) {
  fs.mkdirSync(path.dirname(savePath), { recursive: true });
}

fs.writeFileSync(savePath, code);

return [{
  json: {
    success: true,
    filePath: savePath,
    fileName
  }
}];

const { githubToken, repo, branch, filePath, code, commitMessage } = $json.body;
if (!githubToken || !repo) return [{ json: { error: 'GitHub token and repo required' } }];

const https = require('https');
const apiUrl = `https://api.github.com/repos/${repo}/contents/${filePath}`;

return new Promise((resolve) => {
  const options = {
    method: 'PUT',
    headers: {
      'Authorization': `token ${githubToken}`,
      'User-Agent': 'n8n-coding-assistant',
      'Accept': 'application/vnd.github.v3+json'
    }
  };

  const req = https.request(apiUrl, options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      resolve([{ json: { success: res.statusCode === 201 || res.statusCode === 200, data: JSON.parse(data) } }]);
    });
  });

  req.on('error', (e) => resolve([{ json: { success: false, error: e.message } }]));
  req.write(JSON.stringify({
    message: commitMessage || 'Update from Coding Assistant',
    content: Buffer.from(code).toString('base64'),
    branch
  }));
  req.end();
});

const { code, language, testFramework } = $json.body;
const framework = testFramework || 'vitest';

const testPrompt = `Generate comprehensive ${framework} tests for this ${language} code:

${code}

Include:
1. Happy path tests
2. Edge cases
3. Error handling tests
4. Mock external dependencies
5. TypeScript types if applicable`;

return [{
  json: {
    systemPrompt: 'You are a test engineer. Generate production-ready tests.',
    userPrompt: testPrompt,
    model: 'nvidia/nemotron-3-ultra-550b-a55b',
    temperature: 0.2
  }
}];
